            Err(error) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
                // Keep the error owned by this iteration; the next attempt gets a fresh result.
                let _ = error;
            }
        }
    }
}

